<?php
use App\Application\MarketData\Services\MarketDataEvidenceExportService;
use Illuminate\Support\Facades\DB;
use Tests\Support\UsesMarketDataSqlite;

/** Independent primary source literals; complete semantic admission is separately proved on MariaDB. */
class B19CorrectionEvidenceProofTest extends TestCase
{
    use UsesMarketDataSqlite;
    private $dirs=[];
    protected function setUp(): void {parent::setUp();$this->bootMarketDataSqlite();}
    protected function tearDown(): void {foreach($this->dirs as $d){foreach(glob($d.'/*') as $p)if(is_file($p))unlink($p);rmdir($d);}$this->tearDownMarketDataSqlite();parent::tearDown();}
    private function seed(): array {
        $ids=[];foreach([1,2] as $v){$id=DB::table('eod_runs')->insertGetId(['source'=>'api','trade_date_requested'=>'2026-03-23','terminal_status'=>'SUCCESS','publishability_state'=>'READABLE','created_at'=>'2026-03-25 09:00:00']);$h=[];foreach(['bars','indicators','eligibility'] as $f)$h[$f.'_batch_hash']=hash('sha256','independent '.$f.' input '.$v);$p=DB::table('eod_publications')->insertGetId($h+['trade_date'=>'2026-03-23','run_id'=>$id,'publication_version'=>$v,'is_current'=>$v===2?1:0,'supersedes_publication_id'=>$v===2?$ids[0]['publication']:null,'seal_state'=>'SEALED','created_at'=>'2026-03-25 09:00:00']);DB::table('eod_runs')->where('run_id',$id)->update(['publication_id'=>$p,'publication_version'=>$v]);$ids[]=['run'=>$id,'publication'=>$p,'hashes'=>$h];}
        DB::table('eod_current_publication_pointer')->insert(['trade_date'=>'2026-03-23','publication_id'=>$ids[1]['publication'],'run_id'=>$ids[1]['run'],'publication_version'=>2,'updated_at'=>'2026-03-25 09:00:00']);
        $id=DB::table('eod_dataset_corrections')->insertGetId(['trade_date'=>'2026-03-23','prior_run_id'=>$ids[0]['run'],'new_run_id'=>$ids[1]['run'],'baseline_publication_id'=>$ids[0]['publication'],'replacement_publication_id'=>$ids[1]['publication'],'correction_reason_code'=>'DATASET_HASH_CREATED','correction_reason_note'=>'Independent corrected close106 request','status'=>'PUBLISHED','requested_by'=>'requester-A','requested_at'=>'2026-03-25 08:00:00','approved_by'=>'approver-B','approved_at'=>'2026-03-25 08:30:00','published_at'=>'2026-03-25 09:00:00','current_consumed_at'=>'2026-03-25 09:00:00','created_at'=>'2026-03-25 08:00:00']);return [$id,$ids];
    }
    private function export($id): array {$d=sys_get_temp_dir().'/b19_correction_'.uniqid();$this->dirs[]=$d;app(MarketDataEvidenceExportService::class)->exportCorrectionEvidence($id,$d);return json_decode(file_get_contents($d.'/correction_evidence.json'),true);}
    public static function rules(): array {$a=[];foreach(range(208,227) as $n)$a['S075R'.$n]=['MD-S075-R'.str_pad($n,4,'0',STR_PAD_LEFT)];foreach(array_merge([57],range(59,79)) as $n)$a['S063R'.$n]=['MD-S063-R'.str_pad($n,4,'0',STR_PAD_LEFT)];return $a;}
    /** @dataProvider rules */
    public function test_individual_correction_obligation_from_primary_rows(string $rule): void {
        [$id,$s]=$this->seed();$before=DB::table('eod_dataset_corrections')->where('correction_id',$id)->first();$p=$this->export($id);$l=$p['correction_lifecycle'];$n=(int)substr($rule,-4);
        if(strpos($rule,'S075')!==false){
            $v=[208=>['correction_id',$id],209=>['trade_date','2026-03-23'],210=>['prior_run_id',$s[0]['run']],211=>['new_run_id',$s[1]['run']],212=>['prior_publication_version',1],213=>['new_publication_version',2],214=>['old_hashes',$s[0]['hashes']],218=>['new_hashes',$s[1]['hashes']],222=>['publication_switch',true],223=>['prior_publication_is_current',false],224=>['new_publication_is_current',true]];
            if(isset($v[$n])){$this->assertArrayHasKey($v[$n][0],$p,$rule);$this->assertSame($v[$n][1],$p[$v[$n][0]],$rule);}elseif(in_array($n,[215,216,217,219,220,221])){$side=$n<219?0:1;$f=['bars_batch_hash','indicators_batch_hash','eligibility_batch_hash'][($n-($side?219:215))];$this->assertSame($s[$side]['hashes'][$f],$p[$side?'new_hashes':'old_hashes'][$f],$rule);}elseif($n===225||$n===227){$this->assertSame($s[0]['hashes'],$p['old_hashes']);$this->assertSame($s[1]['hashes'],$p['new_hashes']);$this->assertSame($s[0]['hashes']['bars_batch_hash'],DB::table('eod_publications')->where('publication_id',$s[0]['publication'])->value('bars_batch_hash'));}else{DB::table('eod_dataset_corrections')->where('correction_id',$id)->update(['status'=>'CONSUMED_CURRENT']);$q=$this->export($id);$this->assertFalse($q['publication_switch']);$this->assertNull($q['new_publication']);}
        }else{
            switch($n){case 57:case 79:$this->assertSame($s[0]['publication'],$p['prior_publication']['publication_id']);$this->assertSame($s[1]['publication'],$p['new_publication']['publication_id']);break;case 59:$this->assertSame($id,$p['correction_id']);break;case 60:case 71:$this->assertSame(['approved_by'=>'approver-B','approved_at'=>'2026-03-25 08:30:00'],$p['approval']);break;case 61:$this->assertSame('2026-03-23',$p['trade_date']);break;case 62:case 72:$this->assertSame($s[0]['publication'],$l['baseline_publication_id']);break;case 63:case 73:$this->assertSame($s[1]['run'],$l['candidate_run_id']);break;case 64:case 75:$this->assertSame($s[0]['hashes'],$p['old_hashes']);break;case 65:case 76:$this->assertSame($s[1]['hashes'],$p['new_hashes']);break;case 66:$this->assertSame($s[0]['publication'],$p['baseline_historical_publication_proof']['publication_id']);$this->assertSame($s[1]['publication'],$p['candidate_historical_publication_proof']['publication_id']);break;case 67:$this->assertArrayHasKey('supersession',$p);$this->assertSame($s[0]['publication'],$p['supersession']['supersedes_publication_id']);break;case 68:case 74:$this->assertSame('Publication hash set changed and requires audit comparison.',$p['comparison_summary']);break;case 69:case 77:$this->assertTrue($p['publication_switch']);break;case 70:$this->assertSame('Independent corrected close106 request',$l['reason_note']);$this->assertSame('DATASET_HASH_CREATED',$l['reason_code']);break;case 78:$this->assertArrayHasKey('current_publication',$p);$this->assertIsArray($p['current_publication']);$this->assertSame($s[1]['publication'],$p['current_publication']['publication_id']);break;}
        }
        if($rule==='MD-S075-R0226') DB::table('eod_dataset_corrections')->where('correction_id',$id)->update(['status'=>'PUBLISHED']); // restore deliberate counterfactual
        // Seeded legacy rows prove exact projection/readability, not complete identity admission.
        $this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);$this->assertSame(json_encode($before),json_encode(DB::table('eod_dataset_corrections')->where('correction_id',$id)->first()),$rule);
    }
    public function test_later_supersession_does_not_erase_the_correction_switch_event(): void {[$id,$s]=$this->seed();DB::table('eod_publications')->where('publication_id',$s[1]['publication'])->update(['is_current'=>0]);$p=$this->export($id);$this->assertTrue($p['publication_switch']);$this->assertFalse($p['new_publication_is_current']);}
    public function test_invalid_approval_calendar_is_explicitly_unavailable(): void {[$id]=$this->seed();DB::table('eod_dataset_corrections')->where('correction_id',$id)->update(['approved_at'=>'2026-02-30 09:00:00']);$p=$this->export($id);$this->assertContains('approval.approved_at',$p['evidence_admission']['missing_sections']);}
    public function test_matching_missing_hashes_do_not_establish_unchanged(): void {[$id,$s]=$this->seed();DB::table('eod_publications')->whereIn('publication_id',[$s[0]['publication'],$s[1]['publication']])->update(['bars_batch_hash'=>null,'indicators_batch_hash'=>null,'eligibility_batch_hash'=>null]);$p=$this->export($id);$this->assertSame('UNKNOWN',$p['changed_decision']);$this->assertSame('Comparison unavailable: complete prior and replacement hash sets are required.',$p['comparison_summary']);$this->assertSame('ADMITTED_INCOMPLETE',$p['evidence_admission']['evidence_admission_state']);}
    public function test_cancelled_unexecuted_request_does_not_invent_unchanged(): void {[$id]=$this->seed();DB::table('eod_dataset_corrections')->where('correction_id',$id)->update(['status'=>'CANCELLED','new_run_id'=>null,'replacement_publication_id'=>null]);$p=$this->export($id);$this->assertSame('UNKNOWN',$p['changed_decision']);$this->assertFalse($p['publication_switch']);}
    public function test_impact_readability_guard_rejects_missing_seal_or_contradictory_run_state(): void {$o=app(\App\Application\MarketData\Services\BackfillLifecycleOrchestrator::class);$m=new \ReflectionMethod($o,'isReadableRun');$m->setAccessible(true);$good=['terminal_status'=>'SUCCESS','publishability_state'=>'READABLE','coverage_gate_state'=>'PASS','sealed_at'=>'2026-03-25 09:00:00'];$this->assertTrue($m->invoke($o,(object)$good));foreach(['terminal_status'=>'FAILED','publishability_state'=>'NOT_READABLE','coverage_gate_state'=>'FAIL','sealed_at'=>null] as $f=>$v)$this->assertFalse($m->invoke($o,(object)array_replace($good,[$f=>$v])),$f);}
    public function test_bounded_impact_export_excludes_provider_payload_checkpoint_and_credentials(): void {$r=DB::table('eod_runs')->insertGetId(['source'=>'api','trade_date_requested'=>'2026-03-23','terminal_status'=>'FAILED','notes'=>'publication_reprocess_state=REPUBLISHED; publication_reprocess_republication_mode=AUTOMATED_READABLE_CORRECTION; publication_reprocess_correction_ids=17; raw_provider_payload=RAW_BODY_MARKER; checkpoint_body=CHECKPOINT_MARKER; access_token=PRIVATE_MARKER','created_at'=>'2026-03-25 09:00:00']);$d=sys_get_temp_dir().'/b19_impact_bounded_'.uniqid();$this->dirs[]=$d;app(MarketDataEvidenceExportService::class)->exportRunEvidence($r,$d);$s=json_decode(file_get_contents($d.'/run_summary.json'),true);$this->assertSame('AUTOMATED_READABLE_CORRECTION',$s['publication_reprocess_summary']['republication_mode']);$this->assertSame([17],$s['publication_reprocess_summary']['correction_ids']);foreach(glob($d.'/*') as $f)foreach(['RAW_BODY_MARKER','CHECKPOINT_MARKER','PRIVATE_MARKER'] as $bad)$this->assertStringNotContainsString($bad,file_get_contents($f));}
    public function test_contradictory_consumed_status_cannot_hide_an_actual_replacement(): void {[$id]=$this->seed();DB::table('eod_dataset_corrections')->where('correction_id',$id)->update(['status'=>'CONSUMED_CURRENT']);$p=$this->export($id);$this->assertContains('unchanged_replacement_identity',$p['evidence_admission']['missing_sections']);}
    public function test_published_status_with_equal_hashes_is_not_complete_changed_proof(): void {[$id,$s]=$this->seed();DB::table('eod_publications')->where('publication_id',$s[1]['publication'])->update($s[0]['hashes']);$p=$this->export($id);$this->assertContains('published_correction_changed_decision',$p['evidence_admission']['missing_sections']);}
    public function test_current_pointer_version_must_match_its_own_publication(): void {[$id]=$this->seed();DB::table('eod_current_publication_pointer')->update(['publication_version'=>999]);$p=$this->export($id);$this->assertContains('current_publication',$p['evidence_admission']['missing_sections']);}
    public function test_explicitly_blocked_impact_does_not_publish_or_mutate_pointer(): void {[$id]=$this->seed();$before=DB::table('eod_current_publication_pointer')->get()->toJson();$o=app(\App\Application\MarketData\Services\BackfillLifecycleOrchestrator::class);$m=new \ReflectionMethod($o,'executePublicationReprocessForCase');$m->setAccessible(true);$p=$m->invoke($o,['requested_date'=>'2026-03-20','publication_reprocess_state'=>'PENDING_PROMOTE','publication_reprocess_summary'=>['candidate_trade_dates'=>['2026-03-23']],'publication_reprocess_blocked_trade_dates'=>'2026-03-23'],'api',false,false,sys_get_temp_dir(),false);$this->assertSame('BLOCKED_REQUIRES_CORRECTION',$p['publication_reprocess_state']);$this->assertSame(0,$p['publication_reprocess_republished_trade_date_count']);$this->assertSame($before,DB::table('eod_current_publication_pointer')->get()->toJson());}
}
